#include <iostream>
#include <cstring>
#include <cctype>
#include <queue>
#include <climits>
using namespace std;

struct Edge {
    int to, capacity, next;
};

const int dx[] = {-1, 1, 0, 0};
const int dy[] = {0, 0, -1, 1};
const int MAXN = 20;
const int MAX_NODES = 1000;
const int MAX_EDGES = 1000000;

Edge edges[MAX_EDGES];
int head[MAX_NODES];
int edge_idx = 1;

int S, T, n, t, INF;
int dist[MAXN][MAXN];
int depth[MAXN][MAXN];
int node_id[MAXN][MAXN];
int sink_node[MAXN][MAXN];
int queue_bfs[MAX_NODES * 1000];
int queue_dinic[MAX_NODES];
int depth_dinic[MAX_NODES];

char grid1[MAXN][MAXN];
char grid2[MAXN][MAXN];

void insert_edge(int u, int v, int cap) {
    edges[++edge_idx] = {v, cap, head[u]};
    head[u] = edge_idx;

    edges[++edge_idx] = {u, 0, head[v]};
    head[v] = edge_idx;
}

void bfs_propagate(int sx, int sy, bool mode) {
    int front = 0, rear = 0;
    queue_bfs[rear++] = sx * 1000 + sy;

    memset(dist, 0x3f, sizeof(dist));
    INF = dist[0][0];
    dist[sx][sy] = 0;

    while (front < rear) {
        int cur = queue_bfs[front++];
        int x = cur / 1000;
        int y = cur % 1000;

        if (mode && sink_node[x][y] && dist[x][y] <= t && dist[x][y] <= depth[x][y]) {
            insert_edge(node_id[x][y], sink_node[x][y], INF);
        }

        if (dist[x][y] > t || dist[x][y] >= depth[x][y]) continue;

        if (node_id[x][y] == 3 && sink_node[x][y] == 9) {
            printf("%d\n", dist[x][y]);
        }

        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && isdigit(grid1[nx][ny]) && dist[nx][ny] == INF) {
                dist[nx][ny] = dist[x][y] + 1;
                queue_bfs[rear++] = nx * 1000 + ny;
            }
        }
    }
}

bool build_level_graph() {
    memset(depth_dinic, 0, sizeof(depth_dinic));
    int front = 0, rear = 0;
    queue_dinic[rear++] = S;
    depth_dinic[S] = 1;

    while (front < rear) {
        int u = queue_dinic[front++];
        for (int e = head[u]; e; e = edges[e].next) {
            int v = edges[e].to;
            if (depth_dinic[v] || !edges[e].capacity) continue;
            depth_dinic[v] = depth_dinic[u] + 1;
            queue_dinic[rear++] = v;
            if (v == T) return true;
        }
    }
    return false;
}

int dfs_dinic(int u, int flow_limit) {
    if (u == T) return flow_limit;
    int total_pushed = 0;

    for (int e = head[u]; e && flow_limit; e = edges[e].next) {
        int v = edges[e].to;
        if (depth_dinic[v] != depth_dinic[u] + 1 || !edges[e].capacity) continue;

        int pushed = dfs_dinic(v, min(flow_limit, edges[e].capacity));
        if (pushed) {
            edges[e].capacity -= pushed;
            edges[e ^ 1].capacity += pushed;
            total_pushed += pushed;
            flow_limit -= pushed;
        }
    }

    if (!total_pushed) depth_dinic[u] = -1;
    return total_pushed;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n_val, t_val;
    cin >> n_val >> t_val;
    n = n_val;
    t = t_val;

    for (int i = 1; i <= n; ++i) {
        cin >> grid1[i] + 1;
    }
    for (int i = 1; i <= n; ++i) {
        cin >> grid2[i] + 1;
    }

    memset(depth, 0x3f, sizeof(depth));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                bfs_propagate(i, j, false);
            }
        }
    }
    memcpy(depth, dist, sizeof(dist));

    int node_counter = 1;
    S = 0;
    T = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] > '0' && grid1[i][j] <= '9') {
                node_id[i][j] = ++node_counter;
                insert_edge(S, node_id[i][j], grid1[i][j] - '0');
            }
            if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                sink_node[i][j] = ++node_counter;
                insert_edge(sink_node[i][j], T, grid2[i][j] - '0');
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (node_id[i][j]) {
                bfs_propagate(i, j, true);
            }
        }
    }

    int max_flow = 0;
    while (build_level_graph()) {
        max_flow += dfs_dinic(S, INF);
    }

    cout << max_flow << '\n';
    return 0;
}
